<?php
require_once __DIR__.'/../../includes/staff/auth.php';require_login();$pdo=staff_db();
$materials=$pdo->query("SELECT m.*,mc.name category_name,(SELECT COUNT(*) FROM material_sizes ms WHERE ms.material_id=m.id AND ms.is_active=1) size_count FROM materials m LEFT JOIN material_categories mc ON mc.id=m.category_id WHERE m.is_active=1 ORDER BY mc.sort_order,m.name")->fetchAll();$pageTitle='Material Catalogue';require __DIR__.'/../../includes/staff/header.php';?>
<main class="staff-content"><div class="page-head"><div><p class="eyebrow">Costing</p><h1>Material catalogue</h1><p class="muted">Current materials, units, standard costs and waste allowances used by costing tools.</p></div><?php if(can('material.manage')):?><a class="btn primary" href="<?= h(ideare_root_url('staff/admin/materials.php')) ?>">Manage catalogue</a><?php endif;?></div><section class="staff-panel table-panel"><table><thead><tr><th>Material</th><th>Category</th><th>Brand</th><th>Unit</th><th>Cost</th><th>Waste</th><th>Sizes</th><th>Supplier</th></tr></thead><tbody><?php foreach($materials as $m):?><tr><td><b><?= h($m['name']) ?></b><small><?= h($m['material_code']) ?></small></td><td><?= h($m['category_name']?:'—') ?></td><td><?= h($m['brand']?:'—') ?></td><td><?= h(str_replace('_',' ',$m['unit_type'])) ?></td><td><?= money($m['default_unit_cost']) ?></td><td><?= h($m['default_waste_percent']) ?>%</td><td><?= (int)$m['size_count'] ?></td><td><?= h($m['supplier_name']?:'—') ?></td></tr><?php endforeach;?></tbody></table></section></main><?php require __DIR__.'/../../includes/staff/footer.php';?>
